// Independent absent-focus text oracle. Original code, frame setup, glyphs,
// close and scroll all execute through Legacy CPU. Expected artwork is decoded
// only from original WRAM/VRAM. Host sound/tick and completed JP DMA are explicit
// boundaries; no expected pixel is generated by the native text implementation.
// JP only: OPEN_WINDOW_TABLE indexed by $fffe resolves to $7f8c24, not the
// adjacent WINDOW_TAIL word in bank $7e. Fixture input explicitly supplies the
// same physical ambient slot to both implementations. LOAD_WINDOW_GFX,
// CREATE/CLOSE_WINDOW, PRINT_LETTER, PRINT_NEWLINE and DISPLAY_TEXT execute
// their unchanged source bodies. WINDOW_TICK, PLAY_SOUND and frame wait return
// at declared external host seams; callbacks perform real source calls with
// separate DP locals and preserve the suspended caller's locals/return stack.
// Forced-blank DMA executes normally. Only its already-completed JP semaphore
// is acknowledged before C439E2/C43BE8, without running an unrelated NMI loop.
// Canvas expectations decode actual source descriptors and VRAM; scene checks
// use the original PPU renderer. They do not prove a full world/audio scheduler.
#include "eb/asset_store.hpp"
#include "eb/main_cpu_65816.hpp"
#include "eb/snes_bus.hpp"
#include "generated_assets.hpp"
#include "eb/native/dialogue/fonts.hpp"
#include "eb/native/dialogue/window_graphics.hpp"
#include "eb/native/dialogue/conversation.hpp"
#include <algorithm>
#include <array>
#include <cstdint>
#include <functional>
#include <iostream>
#include <memory>
