        cpu.set_runtime(eb::MainCpuRuntime::Legacy);cpu.emulation_mode=false;cpu.direct_page=0x1e00;cpu.stack_pointer=0x1fff;cpu.data_bank=0x7e;cpu.status_register=eb::MainCpu65816::InterruptDisable;
        bus->work_ram[0xd]=0x80;bus->write_byte(0x2100,0x80);call(0xc200d9,true);call(0xc43be8,true);
        bus->work_ram[0x9c7e]=1;
        for(unsigned member=0;member<4;++member)for(unsigned i=0;i<4;++i)bus->work_ram[0x9c7f+member*94+i]=0x41+i;
        call(0xc459ab,true);put32(0x1e0e,0x7f0000);call(0xc08616,true,0,0x3800,0x6000);open(1);
        bus->work_ram[0x991a]=1;
